ent()):?><form method="post"><?=support_csrf_field()?><input type="hidden" name="action" value="decision"><input type="hidden" name="version" value="<?=(int)$v['id']?>"><label>Decision<select name="choice"><option value="changes">Request changes</option><option value="approved">Approve this version</option></select></label><label>Feedback<textarea name="feedback" maxlength="5000" rows="3"></textarea></label><label class="check"><input type="checkbox" name="confirm" value="1" required>I confirm my decision applies to this exact version.</label><button class="btn gold">Record decision →</button></form><?php elseif($v['feedback']):?><p><?=nl2br(esc($v['feedback']))?></p><?php endif;?></article><?php endforeach;if(!$versions)echo '<p>No reviews have been published yet.</p>';?></div>
<div><article class="workspace-card"><h2>Project conversation</h2><?php $messageRows=contacts_ready()?all('SELECT m.*,ct.name AS contact_name FROM '.table('studio_messages').' m LEFT JOIN '.table('studio_contacts').' ct ON m.author_type=\'contact\' AND ct.id=m.author_id WHERE m.job_id=? AND m.author_type IN (\'admin\',\'client\',\'contact\') ORDER BY (m.id=?) DESC,m.id DESC LIMIT 100',[$jobId,(int)($_GET['focus_message']??0)]):all('SELECT * FROM '.table('studio_messages').' WHERE job_id=? AND author_type IN (\'admin\',\'client\',\'contact\') ORDER BY (id=?) DESC,id DESC LIMIT 100',[$jobId,(int)($_GET['focus_message']??0)]);foreach($messageRows as $m):?><div class="workspace-message" id="message-<?=(int)$m['id']?>"><small><?=esc($m['author_type']==='admin'?'Studio':($m['author_type']==='contact'?($m['contact_name']??'Contact'):'Client'))?> · <?=esc($m['created_at'])?> UTC</small><?=esc($m['body'])?></div><?php endforeach;?><?php if(!support_current()||support_can('support.write')):?><form method="post"><?=support_csrf_field()?><input type="hidden" name="action" value="message"><label>Your message<textarea name="body" maxlength="5000" minlength="2" required rows="4"></textarea></label><button class="btn gold">Send message →</button></form><?php else:?><p>Support messages require separate write permission.</p><?php endif;?></article>
<article class="workspace-card"><h2>Private project files</h2><?php foreach(all('SELECT * FROM '.table('studio_files').' WHERE job_id=? ORDER BY created_at DESC',[$jobId]) as $f):?><p id="file-<?=esc($f['id'])?>"><?php if((!support_current()||support_can('support.download'))&&$canDownloads):?><a href="<?=esc(studio_url(['file'=>$f['id']]))?>"><?=esc($f['original_name'])?> ↓</a><?php else:?><?=esc($f['original_name'])?> · Download permission required<?php endif;?> <small><?=number_format($f['bytes']/1024)?> KB</small></p><?php endforeach;?><?php if(!support_current()||support_can('support.write')):?><form method="post" enctype="multipart/form-data"><?=support_csrf_field()?><input type="hidden" name="action" value="upload"><label>PDF, PNG or JPEG • up to 8 MB<input name="document" type="file" accept=".pdf,.png,.jpg,.jpeg" required></label><button class="btn outline">Upload privately ↑</button></form><?php endif;?><p class="hint">Do not upload passwords or payment-card details. Files are private downloads, not public portfolio media.</p></article></div></div><?php endif;?>
